from decimal import Decimal, ROUND_HALF_UP

def vat_breakdown(lines: list[dict], mode: str) -> dict:
    if mode not in ("PER_LINE", "PER_INVOICE"):
        raise ValueError("invalid mode")
    if not isinstance(lines, list):
        raise ValueError("lines must be a list")
    if len(lines) == 0:
        return {"net": Decimal("0.00"), "vat": Decimal("0.00"), "gross": Decimal("0.00"), "by_rate": {}}
    cents = Decimal("0.01")
    # validated entries: list of (exact_net, quantized_not_used, canonical_key, rate_decimal)
    parsed = []
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError("line must be a dict")
        if "quantity" not in line or "unit_net" not in line or "vat_rate" not in line:
            raise ValueError("missing key")
        q = line["quantity"]
        if isinstance(q, bool) or not isinstance(q, int):
            raise ValueError("invalid quantity")
        if q <= 0:
            raise ValueError("invalid quantity")
        u = line["unit_net"]
        if not isinstance(u, str):
            raise ValueError("invalid unit_net")
        try:
            du = Decimal(u)
        except Exception:
            raise ValueError("invalid unit_net")
        if not du.is_finite():
            raise ValueError("invalid unit_net")
        if du < 0:
            raise ValueError("invalid unit_net")
        exp = du.as_tuple().exponent
        if not isinstance(exp, int):
            raise ValueError("invalid unit_net")
        if exp < 0 and -exp > 4:
            raise ValueError("invalid unit_net")
        r = line["vat_rate"]
        if not isinstance(r, str):
            raise ValueError("invalid vat_rate")
        try:
            dr = Decimal(r)
        except Exception:
            raise ValueError("invalid vat_rate")
        if not dr.is_finite():
            raise ValueError("invalid vat_rate")
        if dr != 0 and dr != 4 and dr != 10 and dr != 21:
            raise ValueError("invalid vat_rate")
        if dr == 21:
            key = "21"
        elif dr == 10:
            key = "10"
        elif dr == 4:
            key = "4"
        else:
            key = "0"
        rate_dec = Decimal(key)
        parsed.append((du, q, key, rate_dec))
    by_rate = {}
    if mode == "PER_LINE":
        groups = {}
        for du, q, key, rate_dec in parsed:
            exact = du * q
            line_net = exact.quantize(cents, rounding=ROUND_HALF_UP)
            line_vat = (line_net * rate_dec / Decimal(100)).quantize(cents, rounding=ROUND_HALF_UP)
            if key not in groups:
                groups[key] = [Decimal("0.00"), Decimal("0.00"), rate_dec]
            groups[key][0] += line_net
            groups[key][1] += line_vat
        for key, (gnet, gvat, _r) in groups.items():
            gross = gnet + gvat
            by_rate[key] = {"net": gnet, "vat": gvat, "gross": gross}
    else:
        exact_sums = {}
        rate_by_key = {}
        for du, q, key, rate_dec in parsed:
            exact = du * q
            if key not in exact_sums:
                exact_sums[key] = Decimal(0)
                rate_by_key[key] = rate_dec
            exact_sums[key] += exact
        for key, exact_sum in exact_sums.items():
            rate_dec = rate_by_key[key]
            gnet = exact_sum.quantize(cents, rounding=ROUND_HALF_UP)
            gvat = (gnet * rate_dec / Decimal(100)).quantize(cents, rounding=ROUND_HALF_UP)
            gross = gnet + gvat
            by_rate[key] = {"net": gnet, "vat": gvat, "gross": gross}
    total_net = Decimal("0.00")
    total_vat = Decimal("0.00")
    for g in by_rate.values():
        total_net += g["net"]
        total_vat += g["vat"]
    total_gross = total_net + total_vat
    return {"net": total_net, "vat": total_vat, "gross": total_gross, "by_rate": by_rate}
